package com.hs.jxc.it;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.hs.jxc.pur.*;
import com.hs.jxc.common.api.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;

class PurchaseImportTraceIT extends PurchaseImportFixture {
    @Autowired PurchaseImportTraceService trace;
    @Autowired PurchaseImportDraftService drafts;
    @Autowired PurchaseImportProductService review;
    @DynamicPropertySource static void draftConfig(DynamicPropertyRegistry r){r.add("jxc.purchase-import.draft-creation.enabled",()->true);}
    @BeforeEach void permissions(){owner.update("UPDATE sys_role SET permissions=permissions||'[\"md:product:view\"]'::jsonb WHERE id=801");}
    @SuppressWarnings("unchecked") Map<String,Object> map(Object value){return (Map<String,Object>)value;}
    @SuppressWarnings("unchecked") List<Map<String,Object>> groups(Map<String,Object>b){return (List<Map<String,Object>>)b.get("groups");}
    @SuppressWarnings("unchecked") List<Map<String,Object>> todos(Map<String,Object>g){return (List<Map<String,Object>>)g.get("feeTodos");}
    Map<String,Object> source(int count){var b=upload(UUID.randomUUID().toString());var doc=document();var rs=new ArrayList<Map<String,Object>>();for(int n=0;n<count;n++){var v=values();v.put("freight","800");v.put("saleUnitPrice","99");v.put("landedUnitCost","60");rs.add(Map.of("sourceSheet","采购","sourceRow",n+2,"originalValues",Map.of("H","800","E","99"),"rawNumericTexts",Map.of("H","800"),"formulas",Map.of("I","G2+H2"),"cachedValues",Map.of("I","60"),"normalizedValues",v));}doc.put("rows",rs);doReturn(doc).when(parser).parse(any(),anyString(),anyLong(),anyString(),isNull());tasks.execute(101,task(b));return drafts.previews(actor,id(b),Map.of("batchVersion",imports.get(actor,id(b)).get("version")));}
    Map<String,Object> item(List<Long> ids,String scope,String amount,String currency,boolean confirm){var out=new LinkedHashMap<String,Object>();out.put("sourceRowIds",ids);out.put("scope",scope);out.put("amount",amount);out.put("currency",currency);out.put("reason","人工核对整单/行归属和原币种");out.put("confirm",confirm);return out;}
    List<Long> rowIds(Map<String,Object>b){return rows(b).stream().map(r->((Number)r.get("id")).longValue()).toList();}
    Map<String,Object> save(Map<String,Object>b,Map<String,Object>g,List<Map<String,Object>> items){return trace.save(actor,id(b),((Number)g.get("id")).longValue(),Map.of("version",g.get("feeTodosVersion"),"items",items,"sourceBasisHash",g.get("sourceBasisHash")));}
    @Test void sixtyRepeatedFreightCellsProduceOneUnresolvedSetAndNeverAComputedTotal(){var b=source(60);var g=groups(b).getFirst();assertThat(todos(g)).hasSize(1);assertThat(todos(g).getFirst()).containsEntry("amount",null).containsEntry("currency",null).containsEntry("scope",null).containsEntry("status","PENDING").containsEntry("reviewStatus","UNRESOLVED");assertThat(todos(g).getFirst().get("sourceRows")).asList().hasSize(60);assertThat(g.get("sourceEvidence")).asList().hasSize(60);assertThat(owner.queryForObject("SELECT count(*) FROM lgs_fee",Integer.class)).isZero();}
    @Test void explicitOrderFeeRemainsOnePendingTodoAndKeepsOriginalMoney(){var b=source(2);var g=groups(b).getFirst();var result=save(b,g,List.of(item(rowIds(b),"ORDER","800","USD",true)));assertThat(todos(result)).hasSize(1);assertThat(todos(result).getFirst()).containsEntry("amount","800.0000000000").containsEntry("status","PENDING").containsEntry("reviewStatus","CONFIRMED").containsEntry("registeredReference",null);assertThat(result.get("version")).isEqualTo(g.get("version"));assertThat(result.get("feeTodosVersion")).isNotEqualTo(g.get("feeTodosVersion"));assertThat(rows(imports.get(actor,id(b))).getFirst()).containsEntry("freight","800.0000000000").containsEntry("saleUnitPrice","99.0000000000").containsEntry("landedUnitCost","60.0000000000");assertThat(owner.queryForObject("SELECT count(*) FROM lgs_fee",Integer.class)).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM cst_inbound_cost",Integer.class)).isZero();}
    @Test void unknownScopeCurrencyAndAmountCannotBeConfirmedButExplicitZeroCan(){var b=source(1);var g=groups(b).getFirst();for(var bad:List.of(item(rowIds(b),null,"800","USD",true),item(rowIds(b),"ORDER",null,"USD",true),item(rowIds(b),"ORDER","800",null,true)))assertThatThrownBy(()->save(b,g,List.of(bad))).isInstanceOf(ApiException.class).extracting("status").isEqualTo(400);assertThat(todos(save(b,g,List.of(item(rowIds(b),"LINE","0","USD",true)))).getFirst()).containsEntry("amount","0.0000000000");}
    @Test void duplicateSourceCoverageAndMultiRowLineScopeAreRejected(){var b=source(2);var g=groups(b).getFirst();assertThatThrownBy(()->save(b,g,List.of(item(rowIds(b),"LINE","800","USD",true)))).isInstanceOf(ApiException.class);var one=List.of(rowIds(b).getFirst());assertThatThrownBy(()->save(b,g,List.of(item(one,"ORDER","800","USD",true),item(one,"LINE","800","USD",true)))).isInstanceOf(ApiException.class);assertThat(todos(save(b,g,List.of(item(one,"LINE","800","USD",true))))).hasSize(2);}
    @Test void sourceChangesInvalidatePriorFeeReviewWithoutDeletingItsEvidence(){var b=source(1);var g=groups(b).getFirst();var reviewed=save(b,g,List.of(item(rowIds(b),"ORDER","800","USD",true)));var row=rows(imports.get(actor,id(b))).getFirst();var v=values();v.put("freight","900");imports.saveRow(actor,id(b),rowIds(b).getFirst(),Map.of("version",row.get("version"),"values",v));var latest=groups(imports.get(actor,id(b))).getFirst();assertThat(todos(latest).getFirst()).containsEntry("reviewStatus","STALE").containsEntry("amount","800.0000000000");assertThat(latest.get("sourceEvidence")).asString().contains("900.0000000000","800","G2+H2");assertThatThrownBy(()->save(b,reviewed,List.of(item(rowIds(b),"ORDER","800","USD",true)))).isInstanceOf(ApiException.class).extracting("code").isEqualTo("PUR_IMPORT_SOURCE_CHANGED");}
    @Test void arbitraryRegistrationReferencesAndStaleFeeVersionsCannotBeSaved(){var b=source(1);var g=groups(b).getFirst();var supplied=item(rowIds(b),"ORDER","800","USD",true);supplied.put("registeredReference",Map.of("id",123));assertThatThrownBy(()->save(b,g,List.of(supplied))).isInstanceOf(ApiException.class);save(b,g,List.of(item(rowIds(b),"ORDER","800","USD",true)));assertThatThrownBy(()->save(b,g,List.of(item(rowIds(b),"ORDER","800","USD",true)))).isInstanceOf(ApiException.class).extracting("status").isEqualTo(409);}
    @Test void revokedGroupBookCannotLeakThroughBatchTrace(){var b=source(1);owner.update("INSERT INTO fin_book(id,country_id,entity_id,code,name,base_currency,status) VALUES(602,101,301,'B2','Other','MXN','ACTIVE')");owner.update("UPDATE pur_order_import_group SET effective_header=jsonb_set(effective_header,'{bookId}','602')");assertThatThrownBy(()->imports.get(actor,id(b))).isInstanceOf(ApiException.class).extracting("status").isEqualTo(404);assertThatThrownBy(()->save(b,groups(b).getFirst(),List.of(item(rowIds(b),"ORDER","800","USD",true)))).isInstanceOf(ApiException.class).extracting("status").isEqualTo(404);}

    @Test void actualOrderReferenceAppearsOnlyForCreatedGroupAndFeeReviewDoesNotInvalidateItsPreview(){var b=source(2);var second=rows(b).getLast();var v=values();v.put("sourceOrderNo","PO-2");v.put("freight","800");imports.saveRow(actor,id(b),((Number)second.get("id")).longValue(),Map.of("version",1,"values",v));var first=rows(imports.get(actor,id(b))).getFirst();review.decide(actor,id(b),((Number)first.get("id")).longValue(),Map.of("version",1,"decision","EXISTING","productId",501,"unit","PCS"));var grouped=drafts.previews(actor,id(b),Map.of("batchVersion",imports.get(actor,id(b)).get("version")));var g=groups(grouped).stream().filter(group->group.get("sourceOrderNo").equals("PO-1")).findFirst().orElseThrow();var h=header();h.put("termDays",0);h.put("taxRate","0");h.put("priceTaxBasis","EXCLUSIVE");long gid=((Number)g.get("id")).longValue();drafts.saveGroup(actor,id(b),gid,Map.of("groupVersion",g.get("version"),"header",h));var prepared=drafts.previews(actor,id(b),Map.of("batchVersion",imports.get(actor,id(b)).get("version")));var ready=groups(prepared).stream().filter(group->group.get("id").equals(g.get("id"))).findFirst().orElseThrow();save(b,ready,List.of(item(List.of(((Number)first.get("id")).longValue()),"ORDER","800","USD",true)));var created=drafts.create(actor,id(b),gid,Map.of("groupVersion",ready.get("version"),"previewToken",ready.get("previewToken"),"confirm",true),UUID.randomUUID().toString());assertThat(created).containsEntry("createStatus","CREATED");assertThat(todos(created).getFirst()).containsEntry("targetOrderId",created.get("orderId")).containsEntry("reviewStatus","CONFIRMED").containsEntry("status","PENDING");var other=groups(imports.get(actor,id(b))).stream().filter(group->group.get("sourceOrderNo").equals("PO-2")).findFirst().orElseThrow();assertThat(todos(other).getFirst()).containsEntry("targetOrderId",null);assertThat(owner.queryForObject("SELECT count(*) FROM pur_order",Integer.class)).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM lgs_fee",Integer.class)).isZero();}
    @Test void historicalSourceAbsenceIsVisibleWithoutInventingAFileHash(){var b=source(1);owner.update("UPDATE pur_order_import SET source_id=NULL");var g=groups(imports.get(actor,id(b))).getFirst();var source=map(((List<?>)g.get("sourceEvidence")).getFirst());assertThat(source).containsEntry("sourceStatus","SOURCE_UNAVAILABLE").containsEntry("fileSha256",null).containsEntry("fileName",null);}

    @Test void isolatedFeatureDockerSavesPendingFeeReviewAndRestoresOriginalEvidenceOverHttp()throws Exception{String image=System.getProperty("jxc.test.purchase-image");Assumptions.assumeTrue(image!=null,"显式构建M6镜像后执行费用待办HTTP验收");var b=source(1);var g=groups(b).getFirst();try(var app=featureContainer(image,false)){app.start();String root="http://"+app.getHost()+":"+app.getMappedPort(8080)+"/api/v1/pur/order-imports/"+id(b);var http=java.net.http.HttpClient.newHttpClient();var body=Map.of("version",g.get("feeTodosVersion"),"sourceBasisHash",g.get("sourceBasisHash"),"items",List.of(item(rowIds(b),"ORDER","800","USD",true)));var request=java.net.http.HttpRequest.newBuilder(java.net.URI.create(root+"/groups/"+g.get("id")+"/fee-todos")).header("Authorization","Bearer purchase-import-source-test").header("X-Country-Id","101").header("Content-Type","application/json").PUT(java.net.http.HttpRequest.BodyPublishers.ofString(codec.write(body))).build();var response=http.send(request,java.net.http.HttpResponse.BodyHandlers.ofString());assertThat(response.statusCode()).as(response.body()).isEqualTo(200);assertThat(response.body()).contains("FeeTodoV1","PENDING","CONFIRMED","800.0000000000","G2+H2");var get=java.net.http.HttpRequest.newBuilder(java.net.URI.create(root)).header("Authorization","Bearer purchase-import-source-test").header("X-Country-Id","101").GET().build();assertThat(http.send(get,java.net.http.HttpResponse.BodyHandlers.ofString()).body()).contains("sourceBasisHash","originalValues","fileSha256");assertThat(owner.queryForObject("SELECT count(*) FROM lgs_fee",Integer.class)).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM cst_inbound_cost",Integer.class)).isZero();String expected=com.hs.jxc.attachment.AttachmentObjectStore.sha256(java.nio.file.Files.readAllBytes(java.nio.file.Path.of("target/jxc-app-0.1.0-SNAPSHOT.jar")));assertThat(app.execInContainer("sha256sum","/app/app.jar").getStdout()).startsWith(expected+" ");}}
}
